const allResults = [];

// Google Trends RSS
const trendsNodes = [
  { name: 'Trends SN', node: 'Trends \u2014 S\u00e9n\u00e9gal' },
  { name: 'Trends CI', node: 'Trends \u2014 C\u00f4te d\'Ivoire' },
  { name: 'Trends CM', node: 'Trends \u2014 Cameroun' }
];

// Google News Alerts
const alertNodes = [
  { name: 'Google News Afrique', node: 'Google News RSS \u2014 Afrique' },
  { name: 'Formation en ligne', node: 'Alerte \u2014 Formation en ligne Afrique' },
  { name: 'Entrepreneuriat', node: 'Alerte \u2014 Entrepreneuriat digital Afrique Ouest' },
  { name: 'R\u00e9seaux sociaux', node: 'Alerte \u2014 R\u00e9seaux sociaux Afrique' },
  { name: 'E-commerce Mobile Money', node: 'Alerte \u2014 E-commerce & Mobile Money Afrique' },
  { name: 'IA Afrique', node: 'Alerte \u2014 IA & Tech Afrique' },
  { name: 'Personal Branding', node: 'Alerte \u2014 Personal Branding & Freelance' },
  { name: 'Startup Afrique', node: 'GNews \u2014 Startup Afrique francophone' },
  { name: 'Instagram TikTok', node: 'GNews \u2014 Marketing Instagram TikTok' },
  { name: 'Formation SN', node: 'GNews \u2014 Formation professionnelle S\u00e9n\u00e9gal' },
  { name: 'E-commerce Afrique', node: 'GNews \u2014 E-commerce croissance Afrique' },
  { name: 'IA Marketing', node: 'GNews \u2014 IA et marketing digital' }
];

// Blogs RSS
const blogNodes = [
  { name: 'TechCabal', node: 'RSS \u2014 TechCabal' },
  { name: 'JeuneAfrique', node: 'RSS \u2014 JeuneAfrique' },
  { name: 'HubSpot', node: 'RSS \u2014 HubSpot Marketing' },
  { name: 'Social Media Examiner', node: 'RSS \u2014 Social Media Examiner' }
];

// YouTube XML channels
const ytNodes = [
  { name: 'YT Marketing Mania', node: 'YouTube XML \u2014 Marketing Mania' },
  { name: 'YT Scaler', node: 'YouTube XML \u2014 Scaler (Business)' },
  { name: 'YT Max-Morrys', node: 'YouTube XML \u2014 Max-Morrys' }
];

const allRssNodes = [...trendsNodes, ...alertNodes, ...blogNodes, ...ytNodes];

for (const src of allRssNodes) {
  try {
    const items = $(src.node).all();
    for (const item of items.slice(0, 5)) {
      const j = item.json;
      // YouTube XML format: { title, link, author, published }
      // Standard RSS: { title, link, contentSnippet, pubDate }
      allResults.push({
        title: j.title || '',
        snippet: (j.contentSnippet || j.content || j['media:group']?.['media:description']?.[0] || '').substring(0, 300),
        url: j.link || '',
        source: src.name,
        date: j.pubDate || j.isoDate || j.published || ''
      });
    }
  } catch (e) {}
}

const seen = new Set();
const unique = allResults.filter(r => {
  const key = (r.title || r.snippet).toLowerCase().substring(0, 50);
  if (!key || seen.has(key)) return false;
  seen.add(key);
  return true;
});

return [{ json: { merged_sources: unique, count: unique.length, sources_count: allRssNodes.length, date: new Date().toISOString() } }];

const input = $input.first().json;
const today = new Date().toISOString().split('T')[0];

let parsed;
try {
  if (input.social_media_ideas) {
    parsed = input;
  } else if (input.content?.parts) {
    const text = input.content.parts.map(p => p.text || '').join('');
    parsed = JSON.parse(text);
  } else if (typeof input === 'string') {
    parsed = JSON.parse(input);
  } else {
    parsed = JSON.parse(JSON.stringify(input));
  }
} catch (e) {
  throw new Error('Erreur parsing Gemini: ' + e.message);
}

const items = (parsed.social_media_ideas || []).map(idea => ({
  json: {
    Date: today,
    Sujet: idea.subject || '',
    Angle: idea.angle || '',
    Pertinence_Locale: idea.why_relevant_locally || '',
    Reseaux: (idea.networks || []).join(', '),
    Format: idea.format || '',
    Score: idea.relevance_score || 0,
    Source: idea.source_url || '',
    Hashtags_Locaux: (idea.hashtags_local || []).join(', '),
    Status: 'nouveau'
  }
}));

return items.length ? items : [{ json: { Date: today, Sujet: 'Aucune idée générée', Status: 'erreur' } }];

